import{_ as o,l as s,o as e,c as l,v as t,p as n,x as r,d,i as p,S as A}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"晶体管密度度量","description":"","frontmatter":{"title":"晶体管密度度量","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/transistor-density-metric.md","filePath":"litho/transistor-density-metric.md","lastUpdated":1789023840000}'),E={name:"litho/transistor-density-metric.md"};function h(m,a,c,_,B,S){const i=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="晶体管密度度量" tabindex="-1">晶体管密度度量 <a class="header-anchor" href="#晶体管密度度量" aria-label="Permalink to &quot;晶体管密度度量&quot;">​</a></h1><div class="epigraph"><p>MTr/mm²、NAND2 等效、SRAM 位密度是三种口径；只报其中最大的那张图，比较会偏。</p><footer>—— 对照逻辑密度度量与 SRAM 密度分报的公开惯例</footer></div><p><a href="/litho/cpp-mmp">上一课</a>给出 CPP 与 MMP。缺口是把尺子合成「密度」时口径不一。本课钉晶体管密度度量。IRDS 如何官方化这些趋势，留给[下一课](/litho/irds-roadmap）。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三种常见：高压/高性能库的晶体管密度；NAND2 标准单元等效密度；SRAM 位元密度。助推器与轨道对它们影响不同：埋电源可能大幅改逻辑密度、少改 SRAM。光刻层数与 EUV 插入对 BEOL 密度（布线资源）的影响也不落在同一口径。</p><p>缺口是<strong>口径</strong>，不是再定义 CPP。把 SRAM 密度当逻辑节点进步，或把宣传峰值密度当全芯片可布密度，都会错估光刻负担。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>全芯片可实现密度还含布线拥堵、电源网格、IP 空隙，低于砖的峰值。DTCO 必须报「砖」与「阻塞后」两层。3D 堆叠（CFET、键合）把密度改到垂直，平面 MTr/mm² 开始失效——后课会遇，本课先声明平面口径的边界。</p><p><span class="marginnote">ISSCC 对照有用，但各厂口径仍可能不一致。引用时写清是 SRAM 还是逻辑、是否含 dummy。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>密度 = 计数 / 面积。计数规则（是否含填充管、是否 SRAM）改变分子；面积是否含外围改变分母。光刻只约束面积能否印出，不定义计数规则——但比较光刻进步时必须固定规则。</p>',11)),(e(),n(A,null,{default:r(()=>[p(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20BRICK%5B%22%E5%8D%95%E5%85%83%20%2F%20SRAM%20%E7%A0%96%22%5D%20--%3E%20PEAK%5B%22%E5%B3%B0%E5%80%BC%E5%AF%86%E5%BA%A6%22%5D%0A%20%20ROUTE%5B%22%E6%8B%A5%E5%A0%B5%20%2F%20%E7%94%B5%E6%BA%90%22%5D%20--%3E%20CHIP%5B%22%E5%8F%AF%E5%B8%83%E5%AF%86%E5%BA%A6%22%5D%0A%20%20PEAK%20--%3E%20CMP%5B%22%E8%8A%82%E7%82%B9%E6%AF%94%E8%BE%83%E9%A1%BB%E5%A3%B0%E6%98%8E%E5%8F%A3%E5%BE%84%22%5D%0A%20%20CHIP%20--%3E%20CMP%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不编造某节点 MTr/mm²。不把密度当功耗或性能。平面口径不描述 3D NAND 的比特密度。</p><p>后课默认：比较要写口径；下一课看 IRDS 用哪些表来约束光刻要求。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>逻辑峰值、NAND2 等效、SRAM 是不同密度口径。</li><li>全芯片可布密度低于砖峰值。</li><li>引用公开对照时声明口径与年份。</li><li>出处：密度度量的公开惯例（ISSCC 对照传统）。</li></ul>',5))])}const T=o(E,[["render",h]]);export{u as __pageData,T as default};
